//
// KAPSAM: hiç Osmanlı olmamış, kasitli_bosluk taşımayan k:0 kayıtlar.
// Taban 27 Ağustos 17:50 koşusundan SONRA yeniden ölçüldü:
//   k0 1363 · Osmanlı olmuş 45 · kasitli_bosluk 178 ⇒ HEDEF 1140
//   (önceki ölçümüm 1126 idi ve BAYATLAMIŞTI — koşu sonrası veri değişti)
// 1140 = 1091 yazılan + 49 tur:"bolge" (dolgu noktası, DOKUNULMADI)
//
// ÖLÇÜT — Emre'nin üç şartına göre
//   k1  künyenin `baskent` alanı noktayı ADIYLA gösteriyor · ya da `kd:`te
//       k:1 zaten beyan edilmiş                              KAYNAKLI
//   k4  tur:"kale" ve başkent değil                          VERİDEN
//   k3  ÖTEKİ HEPSİ — "emin değilsen k3 yaz, k1 değil"       VARSAYILAN
//   k2  KASTEN KULLANILMADI: "eyalet/bölge merkezi" için veride kaynaklı
//       bir işaret YOK. Uydurmak yerine k3 yazıldı.
//
// 🟢 HARİTA ETKİSİ — ÖLÇÜLDÜ, ve BEKLENENDEN KÜÇÜK
//   k3 = 280 km = k0'ın bugünkü tavanı ⇒ 900+ kayıt için GEOMETRİK OLARAK
//   HİÇBİR ŞEY DEĞİŞMEZ. k1 adaylarının HİÇBİRİNDE tavan bağlamıyor
//   (hepsi yoğun bölgede). Yalnız birkaç k4 hücresi KÜÇÜLÜYOR.
//   ⇒ Emre "varsın 200-400 km'ye çıksın" dedi; ölçüm şunu söylüyor:
//     hiçbir şey ÇIKMIYOR, yalnız birkaç kale KÜÇÜLÜYOR.
//
// ⚠️ KAÇIRMA ORANI AÇIKÇA YAZILIYOR: künyelerdeki 455 farklı başkent adının
//   166'sı hiçbir noktayla eşleşmedi (%36). Bunların 19'u bulanık olarak
//   arandı, 9'u ELLE ONAYLANDI, 10'u REDDEDİLDİ (5'i farklı şehirdi —
//   erivan≈Merîvan · sis≈Cēsis · ras≈Krasnovodsk · dhar≈Câlandhar ·
//   afyonkarahisar≈Hisar). Kalan 147 ad ya noktası olmayan şehirler ya da
//   Osmanlı kayıtları (kapsam dışı). Kaçırılan bir başkent k3 kalır —
//   yani GÜVENLİ yön, ama oranı BİLİNSİN.
//
// ALANLAR
//   olcut : baskent · kd-beyan · baskent-elle · kale · varsayilan
//   kaynak: "bulunamadı — varsayılan kademe" olanlar UYDURMA DEĞİL,
//           bilerek boş bırakılmış kademe demektir
